  --bs-btn-color: #cdd6f4;
  --bs-btn-hover-color: #b8c5ef;
  --bs-btn-active-color: #b8c5ef;
  --bs-btn-disabled-color: #cdd6f4;
  --bs-btn-bg: #6c7086;
